pub(crate) fn transn_offset(state: MotionState, source_frame: u8) -> Option<Vec3> {
    let index = usize::from(source_frame.saturating_sub(1));
    match state {
        MotionState::EscapeF => ESCAPE_F_TRANSN_OFFSET.get(index).copied(),
        MotionState::EscapeB => ESCAPE_B_TRANSN_OFFSET.get(index).copied(),
        MotionState::TurnRun => TURN_RUN_TRANSN_OFFSET.get(index).copied(),
        _ => None,
    }
}

pub(crate) fn transn_position(state: MotionState, source_frame: u8) -> Option<Vec3> {
    let index = usize::from(source_frame.saturating_sub(1));
    match state {
        MotionState::EscapeF => ESCAPE_F_TRANSN_POSITION.get(index).copied(),
        MotionState::EscapeB => ESCAPE_B_TRANSN_POSITION.get(index).copied(),
        MotionState::TurnRun => TURN_RUN_TRANSN_POSITION.get(index).copied(),
        _ => None,
    }
}
